                                                                                                                                                                                                                     
  CREATE TABLE "CHECK_CHANGE_LIBRARY_DEVICE"                                                                                                                                                              
   (	"LIBRARY_DEVICE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"LIBRARY_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                          
	"DEVICE_CODE" VARCHAR2(200) NOT NULL ENABLE,                                                                                                                                                                        
	"REMARKS" VARCHAR2(4000),                                                                                                                                                                                           
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                                 
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                          
	"CREATION_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                               
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                          
	"UPDATED_DATE" DATE,                                                                                                                                                                                                
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                       
	"COLUMN_NAME" NUMBER(*,0),                                                                                                                                                                                          
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                        
	 PRIMARY KEY ("LIBRARY_DEVICE_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                                
   ) ;                                                                                                                                                                                                               

